 import unittest
from candidate import filter_integers

class TestFilterIntegers(unittest.TestCase):
    def test_filter_empty_list(self):
        self.assertListEqual(filter_integers([]), [])

    def test_filter_only_integers(self):
        self.assertListEqual(filter_integers([1, 2, 3, 4]), [1, 2, 3, 4])

    def test_filter_mixed_list(self):
        self.assertListEqual(filter_integers(['a', 3, 4]), [3, 4])

    def test_filter_list_with_float(self):
        self.assertListEqual(filter_integers([3.14, 5]), [5])

    def test_filter_list_with_bool(self):
        self.assertListEqual(filter_integers([True, False, 5]), [5])

    def test_filter_list_with_str(self):
        self.assertListEqual(filter_integers(['a', '3']), ['3'])

    def test_filter_list_with_list(self):
        self.assertListEqual(filter_integers([[1, 2, 3], ['a', 4]]), [1, 2, 3, 4])

    def test_filter_list_with_dict(self):
        self.assertListEqual(filter_integers({'a': 1, 'b': 2, 'c': 3}), [1, 2, 3])

    def test_filter_list_with_none(self):
        self.assertListEqual(filter_integers([None, 5]), [5])

if __name__ == '__main__':
    unittest.main()
